<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#1e293b;font-size:12px}h1{margin-bottom:4px}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}.muted{color:#64748b}.total{font-size:16px;font-weight:bold;background:#f1f5f9}</style></head><body><h1>Payslip</h1><div><strong>{{ $payslip['employee']->name }}</strong></div><div class="muted">{{ $payslip['period_start']->format('d M Y') }} – {{ $payslip['period_end']->format('d M Y') }} · Break time excluded</div><table><thead><tr><th>Date</th><th>Clock in/out</th><th>Rate</th><th>Hours</th><th class="right">Amount</th></tr></thead><tbody>@foreach($payslip['lines'] as $line)<tr><td>{{ \Carbon\Carbon::parse($line['date'])->format('d M Y') }}</td><td>{{ $line['clock_in']->format('g:i A') }} – {{ $line['clock_out']->format('g:i A') }}</td><td>{{ $line['rate_label'] }}<br><span class="muted">${{ number_format($line['hourly_rate'],2) }}/hr</span></td><td>{{ number_format($line['hours'],2) }}</td><td class="right">${{ number_format($line['amount'],2) }}</td></tr>@endforeach</tbody><tfoot><tr class="total"><td colspan="3" class="right">Gross pay</td><td>{{ number_format($payslip['total_hours'],2) }}</td><td class="right">${{ number_format($payslip['gross_pay'],2) }}</td></tr></tfoot></table></body></html>
